"""Serialisation of generated Home Assistant packages.

Packages are built as plain Python data and serialised here, rather than
rendered from text templates: the structure of the YAML is then guaranteed by
the serialiser instead of by hand-managed indentation.
"""

from __future__ import annotations

import textwrap
from typing import Any

import yaml

_PREAMBLE = (
    "Generated by hass-energy. Do not edit this file by hand; edits are lost on "
    "the next run. Change the project configuration or the generator instead."
)

_COMMENT_WIDTH = 88


class _PackageDumper(yaml.SafeDumper):
    """Dumper that keeps Home Assistant templates readable."""


def _represent_str(dumper: yaml.SafeDumper, data: str) -> yaml.ScalarNode:
    # Templates go out as block scalars whether or not they span lines: block
    # style neither escapes the quotes they are full of nor wraps them.
    is_template = "\n" in data or "{{" in data or "{%" in data
    style = "|" if is_template else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", data, style=style)


def _comment(text: str) -> str:
    lines = textwrap.wrap(text, width=_COMMENT_WIDTH)
    return "\n".join(f"# {line}" for line in lines)


_PackageDumper.add_representer(str, _represent_str)


def render_package(description: str, data: dict[str, Any]) -> str:
    """Serialise one package file, header included.

    The header carries no timestamp and no host details, so regenerating an
    unchanged configuration produces a byte-identical file.
    """

    body = yaml.dump(
        data,
        Dumper=_PackageDumper,
        sort_keys=False,
        default_flow_style=False,
        allow_unicode=True,
        indent=2,
        width=100,
    )
    header = f"{_comment(_PREAMBLE)}\n#\n{_comment(description)}\n"
    return f"{header}\n{body}"
